from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        size = 1
        while size < n:
            size <<= 1

        seg = [0] * (2 * size)
        for i, cap in enumerate(baskets):
            seg[size + i] = cap

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[i << 1], seg[i << 1 | 1])

        unplaced = 0

        for x in fruits:
            if seg[1] < x:
                unplaced += 1
                continue

            pos = 1
            while pos < size:
                left = pos << 1
                if seg[left] >= x:
                    pos = left
                else:
                    pos = left | 1

            seg[pos] = -1
            pos >>= 1
            while pos:
                seg[pos] = max(seg[pos << 1], seg[pos << 1 | 1])
                pos >>= 1

        return unplaced
